        self._lock = threading.Lock()
        self._leases = {}  # resource_id -> {"worker_id": str, "fencing_token": int, "expires_at_ms": int}
        self._highest_issued = {}  # resource_id -> int
        self._last_write = {}  # resource_id -> int
        self._values = {}  # resource_id -> str or None

    def acquire(self, resource_id: str, worker_id: str, ttl_ms: int, now_ms: int) -> dict:
        with self._lock:
            lease = self._leases.get(resource_id)
            if lease is not None and now_ms < lease["expires_at_ms"]:
                return {"granted": False, "fencing_token": None, "expires_at_ms": lease["expires_at_ms"]}
            new_token = self._highest_issued.get(resource_id, 0) + 1
            self._highest_issued[resource_id] = new_token
            expires_at_ms = now_ms + ttl_ms
            self._leases[resource_id] = {"worker_id": worker_id, "fencing_token": new_token, "expires_at_ms": expires_at_ms}
            return {"granted": True, "fencing_token": new_token, "expires_at_ms": expires_at_ms}

    def renew(self, resource_id: str, worker_id: str, fencing_token: int, ttl_ms: int, now_ms: int) -> bool:
        with self._lock:
            lease = self._leases.get(resource_id)
            if lease is not None and lease["worker_id"] == worker_id and lease["fencing_token"] == fencing_token and now_ms < lease["expires_at_ms"] and ttl_ms > 0:
                lease["expires_at_ms"] = now_ms + ttl_ms
                return True
            return False

    def release(self, resource_id: str, worker_id: str, fencing_token: int) -> bool:
        with self._lock:
            lease = self._leases.get(resource_id)
            if lease is not None and lease["worker_id"] == worker_id and lease["fencing_token"] == fencing_token:
                del self._leases[resource_id]
                return True
            return False

    def write_resource(self, resource_id: str, fencing_token: int, value: str, now_ms: int) -> dict:
