                return {"success": False, "reason": "INVALID_ARGUMENT"}
            if not isinstance(now_ms, int) or isinstance(now_ms, bool):
                return {"success": False, "reason": "INVALID_ARGUMENT"}
            if fencing_token <= 0:
                return {"success": False, "reason": "STALE_TOKEN"}
            if self._highest_issued.get(resource_id, 0) == 0:
                return {"success": False, "reason": "STALE_TOKEN"}
            max_token = max(self._highest_issued.get(resource_id, 0), self._last_write.get(resource_id, 0))
            if fencing_token < max_token:
                return {"success": False, "reason": "STALE_TOKEN"}
            self._values[resource_id] = value
            self._last_write[resource_id] = fencing_token
            return {"success": True, "reason": "OK"}

    def read_resource(self, resource_id: str) -> dict:
        with self._lock:
            value = self._values.get(resource_id)
            last_token = self._last_write.get(resource_id, 0)
            return {"value": value, "last_token": last_token}
